#include <bits/stdc++.h>
using namespace std;

const long long MAX_INF = 1e18;
long long result = 0;
vector<int> memoization;

int find_min_moves(long long n) {
    if (n == 0) return 0;
    if (n < (long long)memoization.size() && memoization[n]) return memoization[n];

    long long previous_diff = MAX_INF;
    long long candidate = 1;
    int count_steps = 0;

    while (abs(candidate - n) <= previous_diff) {
        previous_diff = abs(candidate - n);
        candidate = candidate * 10 + 1;
        count_steps++;
    }
    candidate /= 10;

    if (candidate > n && candidate / 10) {
        if (n < (long long)memoization.size()) {
            return memoization[n] = min(count_steps + find_min_moves(abs(candidate - n)),
                                          count_steps - 1 + find_min_moves(abs(candidate / 10 - n)));
        }
        return min(count_steps + find_min_moves(abs(candidate - n)),
                   count_steps - 1 + find_min_moves(abs(candidate / 10 - n)));
    }
    if (n < (long long)memoization.size()) {
        return memoization[n] = count_steps + find_min_moves(abs(candidate - n));
    }
    return count_steps + find_min_moves(abs(candidate - n));
}

int main() {
    ios_base::sync_with_stdio(false);
    long long n; cin >> n;
    memoization.resize(1e7);
    cout << find_min_moves(n);
    return 0;
}
